text(await tools.apply_patch("*** Begin Patch
*** Add File: D:/work/other/ai-writer/acceptance/20261021-long-flow-090-x/cr-expand33.mjs
+import fs from 'node:fs';const P='D:/work/other/ai-writer/acceptance/20261021-long-flow-090-x/scenario/东岸末班船-再扩展验证/分段/0033/';
+const additions={
+'01':{key:'收饭时，母亲把剩的鱼肉',text:'姑娘吃完自己那半面，母亲还留一块在碗底。她以为是刺没挑清，拿筷子想帮，母亲挡一下，说这块自己留最后，方才拌饭吃，鱼味都让饭盖住，现在想单吃。她缩回筷子，等母亲吃，自己取水喝。\n\n母亲问今天的黄上衣同事又说没有，她说就午间那一句，自己发照片给沈禾，拍得只剩袖子，饭倒很显眼。母亲让她把照片找出来，看一眼便笑，说果然先看见饭，若不告诉我穿黄的，我也只当你要问菜。姑娘把手机转回，试着将照片放大，能看的不过一小角膝，索性不放了，夹一小块姜尝。姜吸过汤，辣味仍在，她咽下去，母亲问是不是以为切细便不辣，她赶紧拿杯，两个人又笑起来。\n\n“你自己挑的宽姜。”姑娘说。\n\n“宽的我看得见，想吃再夹。细的你混汤里，自己喝到了吧。”\n\n她笑着认，杯放下后，把桌边那一点汤擦掉，手机挪到干处，没再拍一张给人证明鱼做得怎样。\n\n'},
+'02':{key:'袋口剪开，豆落进盆，她看见混着一小粒碎的，伸手拣出，先做眼前这一盆。',text:null},
+'03':{key:'外头一个人来问桥口往哪边',text:'老何来时看见她的小盒，问带的什么，许蓉说梨，自己切过，叫他愿吃就取一块。他拿了旁边的牙签，挑中稍大那片，吃完嫌不够脆，许蓉说自己特意挑的软一点，不费牙。他道那以后别照我的嘴挑，我还喜欢咬着有声。\n\n许蓉笑说又不是替你买，能顺口吃一块就成。他也笑，将用过的牙签包进纸，不随手插回盒，转去挂自己的袋。她看那片梨剩的汁在盒底，拿盖先搭住，过一会儿再吃，免得风把表面吹干。\n\n老何问她下午一直在不在，她说照旧到六点半，他要是有事先说。他说没别的，自己杯底那点茶叶总塞在滤网，想回去拿细刷，现在取还赶得上。她指指桌边给他留的空处，让杯先搁这边，别用尖东西硬戳。他把杯放下，走前又回头说梨虽软，味倒是好。许蓉道你刚才不是嫌，老何说嫌脆和嫌味是两回事，人已经笑着出门。她端起自己的杯，看他杯内细茶渣贴在网边，没替他倒，挪开值班簿，给两只杯各留一块干地。\n\n'},
+'04':{key:'',text:null}};
+for(const n of ['01','02','03','04']){let s=fs.readFileSync(P+n+'-cr-v1.md','utf8');if(n==='01'||n==='03'){let a=additions[n];if(!s.includes(a.key))throw Error(n);s=s.replace(a.key,a.text+a.key);}if(n==='02')s=s.replace(additions['02'].key,additions['02'].key+'\n\n谭老板在旁边洗一只饭盒，见她拣完没倒水，便问这盆是不是仍照昨儿泡。她说是，抬眼看他手里空盒，问今日带饭没有。他将盒翻过来晾，说想让中午那点饭干一些，家里煮得稀，装盒带来全黏在盖上，今日索性到时再吃。\n\n沈禾说自己也有过，盖一开水往袖子上淌，吃没吃饱先不说，人已经洗过半只手。老板听得笑，将盖子斜放，不同盒底叠一起。她把豆盆的水放好，回来将空袋折起，见老板仍在找个不会倒的位置，便指柜后那只小篮，说盒立那里，旁边也不挡拿东西。\n\n老板照着放，两个盖竟能一齐立住，便说这倒省地方。她伸手拿下一只要用的盆，篮边碰了手背，才发现放得太靠外，又往里送两指宽。两人忙过这一阵，外头第一位客人进来，指的是柜里另一种，沈禾擦手去取，老板在后面将刚晾的盒看一眼，自己拿布擦去底下的水。她给客人包好，听见他说今天先吃别的，便应一声，没替他把午饭全选定。');if(n==='04')s=s.replace('邻铺前日带走的两片','邻铺昨日带走的两片');fs.writeFileSync(P+n+'-cr-v2.md',s,{flag:'wx'});}
*** End Patch"));
