+import fs from 'node:fs';import crypto from 'node:crypto';const P='D:/work/other/ai-writer/acceptance/20261021-long-flow-090-x/scenario/东岸末班船-再扩展验证',sha=x=>crypto.createHash('sha256').update(x).digest('hex');let input=JSON.parse(fs.readFileSync(P+'/.writer/drafts/cr-template-33-r146.json'));const draft='正文/0033-把用过的话带回来-cr-v2.md',body=fs.readFileSync(P+'/'+draft),han=(body.toString().replace(/^#.*$/gm,'').match(/\p{Script=Han}/gu)||[]).length;const E=q=>({unit:33,quote:q});
+const rp='审查/X-CR33最终合章自检-v2.md';const report=`# 第33章最终合章实读自检\n\n同ID知情创作代理自检，不是真人盲读、文学通行证或作者逐项采纳细节。正文${draft}，SHA ${sha(body)}；正文汉字${han}；六实际事件段。先全读v1后另存纠正，FastCtx全读v2的1—100、101—200、201—283，全尾段未省。\n\n## 写前与纲文\n\n实际plan33→有限workflow→写前context/template。原P_X_COAT是不存在的ID，cr-context33和误续发cr-template33均实际失败退出2；当时未写正文。原细纲/原输入保留，冻结CR33_INITIAL，再另存真实P_W_COAT候选、impact/候选原文完整读/影响报告，正式CR33_RECALL_ID_V2未来33起发布。r146真实重取context和模板，冻结来源而非就地改哈希，详见X-CR33细纲ID影响实读-v1。context作者账本17项包括三链，证据省略仅表示旧引用简写，不能当未决消失。\n\n沿V12/A12与新近期纲六段：周四女母煎31所买鱼/不同口味与听戏/母自缝枕套/女洗裤晾；周五沈家父借女画册/肘光闲聊、伤脚需垫凳，店里盒盖与劳动接上；母再穿工装买梨/热剩鱼，自写具体新反馈并值守/分享梨；周午后接椅清接头垫补上胶夹住，20拟价未收/明午先电约取，另柜门仍未定价；女真实到活动室见老师归材料，原纸交阅并带回，练布只展平不新缝；晚归母听转述、工装通风/未洗，女裤洗干回柜，戏/梨/与沈兴趣聊天，远书约留未来。\n\n自然偏差：原近期纲沈父段“自己画册”指父自己翻看，实际写成父明确借沈的八元自有画册，所有权不变，临时保管换手真实发生。没有第四次课，也没有固定周五值班制度；老师在场是到场见到后才成立。第三段母时段横跨值守，第四段另转同日周铺午后，属明确并行视点，不把下午两线串成先后同一人。\n\n## 四语言测试\n\n口语：母鱼尾/宽姜、父“又不是借出去几十本”、梨不脆但味好，人物有不同食欲与兴趣；老师说先折平再缝有对象，未人人说同句人生道理。仍有老师217句及母亲119/女268偏说明口气，列optional_style，非硬错。\n动作所指/限知：饭盒一盒一盖，v1写两个盖真实数错→02-v3；姑娘不能“想起”未见母晨举毯→05-v2明确试着想象，未取得母整日视角；周昨日两木片非前日→04-v2。原v1及旧段保留。纸女→师阅→女，练布只短时师捏后女带回；书沈→父，小白纸未换页，晚去向仅沈文字说父又叫看/未写交还；松椅邻居→周台侧夹胶不坐试/不取件/不付20。\n去抽象/解释测试：147“不替那人安排到头的事”、182“不把空走说成损失”略把写作边界带进叙述，列为可选简化，不是引导更换旧原观察。剧情核心由鱼/洗晾/书/梨/胶合/递纸发生支撑，未靠复述结论加字。\n陌生读者/自然度：新课外交流说明动机、真实进门所见及十来分钟时间限制，老师仅读纸/练布没看衣；回家谈结果未说已重补。06-v2将别扭“问明日有变仍前一天说吧”改为照旧明日互告，星期五→后天周日和25下下周日约一致。\n\n## 硬项与边界\n\n最终未见需阻断本章登记的硬伤；数物/限知候选问题已另版本修正。茶32本次会面兑现保持；衣多次洗后用感真实交还学习关系，达本卷具体反馈目标，但后续穿用/下一课带衣/自己再练仍未发生，T_X_COAT_DAILY保留partial并明写已做和未做。书35/V13同行/各选/是否买书仍pending，33只再次提到两点并拟明日告变。父伤未愈、馒头是否热未写；24原units/正文和观察三字段不得改。周六8:30另一门仍未来，不混30已修纱门。梨/鱼付清无具体新金额，不与旧款合并；松椅20未付，柜门没定价。\n\n这是单章报告，当前28—33滚动完整实读尚未开始，必须33成功record之后另跑before/原生六章完整单调阅读/after和正式review，不能以这次全读补窗口。\n`;
+fs.writeFileSync(P+'/'+rp,report,{flag:'wx'});input.draft=draft;input.summary='第二十五日周四夜母女煎前章买鱼吃、听戏、母亲自缝枕套扣，女洗全天穿的修裤晾。第二十六日周五：沈早晨把自己八元画册借父，父伤脚仍需垫凳/松鞋，父仅拟热馒头；店里照常泡豆/晾饭盒。母再穿工装买梨热剩鱼，自记靠桌认角/抬手未压，16—18:30值守后归家工装挂通风未洗。周午后接邻居松椅拟20未收、清胶垫补上胶夹稳留铺待胶，明午先电话再取；柜门尺寸仅开口仍没接物/定价。女傍晚取新纸/旧练布到活动室真实见老师归材料，纸交阅后带回、练布只展平未新缝，回家转述母且纸背记已看/未带衣，裤已干收柜未再穿。与沈文字聊画/书，明日拟告变、周日14点仍未来，茶不重结、衣具体反馈已到但后续保留partial，书pending。';
+input.changes={characters:{许蓉:'周四夜实际煎鱼吃/余鱼汤冷藏、自缝枕套扣归柜，见女脱洗裤晾，听其一日取纸未挂。周五从柜取工装再穿、买两梨付清无金额/热余鱼，自记靠桌认角与抬手未压而非同负荷；16—18:30值守并与老何分享梨。夜回家换衣，亲看右肘折边后挂房内通风未洗，亲听女说老师读新纸而没看衣/可下回带；听沈父借同册一事仅女念的一句，不共享全部消息。',许蓉女儿:'周四穿修裤一天自述取纸未挂，夜实际脱洗晾/记与母衣分开，帮母穿针但枕套母自缝。周五另裤赴班，傍晚取母周三/周五同张纸、消息确认抬手未压肘，带纸旧练布专程到活动室真实见老师课外归材料；递纸读后接回，练布捏平未新缝，母衣没带/老师未摸衣。夜转述母，纸背记已给老师看未带衣并同练布备课袋留家；摸裤兜里外干，叠回自柜未再穿，薄余布另纸套。与沈仅文字聊师/练布/画册及各看书，拟明日告变、周日14点未赴。',沈禾:'周五清晨从床头取自有八元画册亲借父，原白纸随书/父膝上读，挪凳让父垫脚、空蓝袋仍椅外，父伤未愈/热馒头仅拟；告父女孩周日12:30交完，自己两点约仍未到。照常店内泡豆、与谭晾盒及上工，夜仅消息告诉女父又叫看树/自己想看窗，收女课外见师文字及半块练布手照，非亲见师或母新纸/母衣。书周日仍14点、明日拟互告，不保证店开/买书。',沈成林:'周五清晨早醒用鞋拔拨旧广告，亲从沈手接其八元画册/原白纸随，坐床沿看屋檐问画，伤脚仍松鞋口并需垫凳；热冰箱馒头只是拟等天亮、未写真吃。亲听沈告仍后天周日两点、女12:30忙完，未知全部女孩/老师事。晚上叫沈看画仅沈消息回告，书未写归还给沈。',周岸:'周五午后亲从廖家邻居接松椅，接头胶松/局部坏角，商量只修接处不重涂、拟20未收/有新损另问；实际清胶垫补上胶夹住，留铺台侧待胶未坐试/交回/收钱，明日午后先电话拟取，周六8:30另门仍待。柜门客户电话只报开口，厚薄照片拟明日补，未接物定价。茶约昨日真实坐过，不知许沈反馈线。',谭老板:'周五清晨店里与沈泡豆/晾一盒一盖，今日午饭想吃干些未定实际结果；只知本人店内，不得据此知沈父画册、姑娘课外师谈。',老何:'周五实际在候船室尝许蓉一片梨，谈脆/味并拟回取细刷，杯留桌边；知道许今日照旧至18:30，未写取刷/返程结果，不知母女师谈或其他约。',修衣课老师:'周五课外帮归材料时现场见姑娘，完整读母周三夜/周五用感纸，问清抬手未压与靠桌非同力，知道母衣二洗后再穿仍认角仅来自纸/女转述，未亲见母整下午或实衣。纸递回女，亲看旧练布折边并短示捏平、没新缝；仅听女自裤穿一天取纸未挂/洗后在晾，未来用感未知；下周来/带衣只是可选后续。'},timeline_append:['第二十五日周四夜许家：母实际煎31买的鱼/冷藏余汤、自己缝枕套扣归柜；女修裤穿一天后脱洗晾，钥匙从包回钩，非测试长期承物。','第二十六日周五清晨沈家到店：沈亲借自有八元画册给父/原白纸仍页，父伤脚需垫凳，自己热馒头待天亮仅计划；沈上工泡豆、与谭晾一盒一盖。','同日许蓉再穿母工装买梨付清无数额、热余鱼，自记靠桌认角/抬手未压，下午仍16—18:30值守/尝梨闲谈，晚工装脱挂房内通风/未洗。','同日午后周铺接邻居松椅，拟20未收/清接头垫补上胶夹住留铺；明午先电话拟取，周六8:30另一门仍待；柜门仍未接物/定价。','同日傍晚女先回家读/问新纸，带纸旧练布到活动室见老师归材料，交纸真实读再取回，练布示折平没新缝；不是第四课。','同日夜许家女转述母，纸背记已给老师看/未带衣并随练布放备课袋，修裤干后收自己柜未再穿；与沈字聊书，周六拟告变/周日14点尚未赴。'],ledger:{
