+[28,['各人给自己留时间，母买鞋、周独行、女认自裤里外两处，为早班准备。','去看双鞋。上回外街那家，我站门口没进去。'],['鞋码/脚背实际不合；周途中又有人要他立即看纱门，日常欲望与随叫随到碰撞。','“今天不行？”'],['母多花3元选灰鞋，周不跟去/留照片另约；女裤只记问题不贸然拆。','“今天这会儿不去了。我出来走这一段。'],['母付100找62穿灰鞋回，周4:58回铺接照，女识别里布薄。','女人将五十、十和两张一元摆到柜面'],['母女从催问衣袖转到各自审美/共听戏；选择能不同。','“那你买自己的。我今晚想喝粥。”']],
+[29,['沈兑现五点早班、三点半离店，父独自把早餐吃妥。','自己已经答应五点进门。'],['独守早市/送粉原单末行险漏，父伤脚令热粥搬碗需分步。','问小包是不是临时添的。'],['沈回拨核小包后付清；父关火落碗换布分两步，沈早走后选择睡而非赶洗帘。','她回拨老板补问小包'],['老板3:20返接柜、3:30真走；父吃洗并语音回告，沈已睡一阵。','“今天早回，睡过一阵”'],['父女的照料经本人做完与简短回告形成信任；老板具体接柜释放沈的时间。','她没有站在那里将锅盖再掀一次']],
+[30,['姑娘在第三课修自己的裤里薄处/外开线，接回本人的穿用感受。','今天是自己的裤子。'],['原练布厚、原袋布薄，里外层不同；母衣新用感此刻未回。','垫进去对这条裤有些厚。'],['选择浅米薄料/外灰线，自己缝结，厚余布不混，母衣当晚不全拆。','“可我不想一伸手，先摸着一堆布。”'],['当夜裤兜手纸有限实试，钥匙仍包；母新周三用感另记，未传师。','周三穿，软些，久靠仍认得出；今日出汗'],['母尊重女裤触感偏好，女把自己的手与审美放到前面；老师不替她每针做主。','“你那只手比我还大？”']],
+[31,['周廖各完成午前生活劳动，真留工作外赴茶的半下午。','“到廖师傅家喝茶。”'],['赶用折椅不能当天做，舍掉即时一笔；廖晚问汤也已收火。','自己两点要去河边坐。'],['周明说今日赶不出，午后留14—16/16后回与电话纸，工具包留铺。','“下午你要用，我这边今天赶不出。”'],['周13:40无工具提自杯赴约中；廖已回家吃饭备两杯椅，尚未相见。','他看看时间，一点四十分'],['两人的准备从修物互惠变为彼此知道已吃饭/认毛巾的私约；女沈也只分享有限裤感饭照。','“家里，认门口两条毛巾”']],
+[32,['周真实到廖家坐饮看花，把预留时间用在相处。','他低头看手机，一点五十八'],['工作惯性仍要起身/猜螺丝、电话未接和邻居椅背询问；如何让话从活里离开。','“我午市收完，最想坐一会儿。真坐下，脑子又在数晚间还剩几把葱。”'],['周不现场修椅，廖不强添饼/不重摆全盆；双方聊挂面旧书/旧路并允许静默。','说带过去先看，明天午后他在铺'],['茶凉到近16点离开，周回铺回电，廖洗杯再晚市，劳累并未消失。','下午坐得久，此刻脚仍会累'],['可闲谈、不必以修物招待的朋友关系落实为一次共同度过的下午。','“周岸也来坐。”']],
